import base64, hashlib, hmac, json

def b64(b): return base64.urlsafe_b64encode(b).rstrip(b"=").decode()
def unb64(s): return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))
def _mac(key, msg): return hmac.new(key.encode(), msg.encode(), hashlib.sha256).digest()

def sign(payload, key):
    h = b64(json.dumps({"alg": "HS256", "typ": "JWT"}, separators=(",", ":")).encode())
    p = b64(json.dumps(payload, separators=(",", ":")).encode())
    return f"{h}.{p}.{b64(_mac(key, h + '.' + p))}"

def verify(token, key, now):
    try:
        h, p, s = token.split(".")
        header = json.loads(unb64(h))
    except Exception:
        return "malformed"
    if header.get("alg") != "HS256":
        return "bad alg"
    if not hmac.compare_digest(_mac(key, h + "." + p), unb64(s)):
        return "bad signature"
    claims = json.loads(unb64(p))
    if "exp" not in claims:
        return "no exp"
    if claims["exp"] <= now:
        return "expired"
    return "ok:" + claims["sub"]

tok = sign({"sub": "u1", "exp": 2000}, "secret")
print(verify(tok, "secret", 1000))
h, p, s = tok.split(".")
tampered = h + "." + b64(json.dumps({"sub": "admin", "exp": 2000}, separators=(",", ":")).encode()) + "." + s
print(verify(tampered, "secret", 1000))
none_h = b64(json.dumps({"alg": "none"}).encode())
print(verify(none_h + "." + p + ".", "secret", 1000))
print(verify(tok, "secret", 2000))
print(verify(tok, "wrong", 1000))
